from class12_quran_common import BOOK, Builder, rec, V


def p24():
    b = Builder()
    V(b, 4, 60, 'کیا آپ نے ان لوگوں (کے حال) کو نہیں دیکھا جو دعویٰ کرتے ہیں کہ وہ ایمان رکھتے ہیں اس پر جو آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کی طرف نازل فرمایا گیا اور اس پر (بھی) جو آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) سے پہلے نازل فرمایا گیا وہ چاہتے ہیں کہ (اپنے مقدمات کے) فیصلے کے لیے طاغوت کے پاس جائیں حالاں کہ انھیں حکم دیا گیا تھا کہ وہ اُس (طاغوت) کا انکار کریں اور شیطان چاہتا ہے کہ انھیں گم راہ کر کے بہت دور کی گم راہی میں (ڈال دے)۔',
      'ایا تاسو د هغو خلکو (حال) نه دی لیدلی چې دعوه کوي چې پر هغه څه ایمان لري چې تاسو (صلی الله علیه وعلی آله واصحابه وسلم) ته نازل شوي او پر هغه څه (هم) چې له تاسو (صلی الله علیه وعلی آله واصحابه وسلم) مخکې نازل شوي؟ هغوی غواړي چې (د خپلو قضیو) د پرېکړې لپاره طاغوت ته ورشي، حال دا چې حکم ورته شوی و چې له هغه (طاغوت) انکار وکړي؛ او شیطان غواړي چې هغوی ګمراه کړي او ډېرې لرې ګمراهۍ ته یې (ورګډ کړي).')
    V(b, 4, 61, 'اور جب ان سے کہا جاتا ہے کہ اُس (کلام) کی طرف آؤ جو اللہ نے نازل کیا اور رسول (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کی طرف آؤ (تو) آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) منافقوں کو دیکھیں گے کہ وہ آپ سے روگردانی کرتے ہوئے منہ موڑ لیتے ہیں۔',
      'او کله چې ورته وویل شي چې هغه (کلام) ته راشئ چې الله نازل کړی او رسول (صلی الله علیه وعلی آله واصحابه وسلم) ته راشئ، (نو) تاسو (صلی الله علیه وعلی آله واصحابه وسلم) به منافقان وګورئ چې له تاسو مخ اړوي او بېرته ګرځي.')
    V(b, 4, 62, 'تو اس وقت کیا حال ہوتا ہے جب ان کو کوئی مصیبت پہنچتی ہے اُن (کرتوتوں) کی وجہ سے جو اُن کے ہاتھوں نے آگے بھیجے پھر وہ آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کے پاس آتے ہیں اللہ کی قسمیں کھاتے ہوئے کہ ہم نے تو صرف بھلائی اور موافقت کا ارادہ کیا۔',
      'نو هغه وخت به څه حال وي چې کله ورته د هغو (کړنو) له امله کوم مصیبت ورسېږي چې د هغوی لاسونو مخکې لېږلي؟ بیا تاسو (صلی الله علیه وعلی آله واصحابه وسلم) ته راځي او په الله قسمونه خوري چې موږ خو یوازې د ښېګڼې او جوړښت اراده کړې وه.')
    V(b, 4, 63, 'یہ وہ لوگ ہیں کہ اللہ جانتا ہے جو اُن کے دلوں میں ہے تو آپ اُن سے درگزر کیجیے اور انھیں نصیحت کیجیے اور اُن سے اُن کے دلوں پر اثر کرنے والی بات کہیے۔',
      'دا هغه خلک دي چې الله پوهېږي څه یې په زړونو کې دي؛ نو تاسو ترې تېر شئ، نصیحت ورته وکړئ او ورته داسې خبره وکړئ چې د هغوی پر زړونو اغېز وکړي.')
    V(b, 4, 64, 'اور ہم نے ہر رسول کو صرف اس لیے بھیجا ہے کہ اللہ کے حکم سے اُس کی اطاعت کی جائے اور اگر وہ لوگ جب اپنی جانوں پر ظلم کر بیٹھے تھے (تو اگر) آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کے پاس آتے پھر اللہ سے بخشش مانگتے اور اُن کے لیے رسول (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) بھی بخشش مانگتے تو ضرور وہ اللہ کو بہت توبہ قبول فرمانے والا نہایت رحم فرمانے والا پاتے۔',
      'او موږ هر رسول یوازې د دې لپاره لېږلی چې د الله په حکم یې اطاعت وشي؛ او که هغه خلک کله چې یې پر خپلو ځانونو ظلم کړی و، تاسو (صلی الله علیه وعلی آله واصحابه وسلم) ته راغلي وای، بیا یې له الله بښنه غوښتې وای او رسول (صلی الله علیه وعلی آله واصحابه وسلم) هم ورته بښنه غوښتې وای، نو خامخا به یې الله ډېر توبه قبلوونکی، بې‌حده مهربان موندلی وای.')
